+	          bli_is_unaligned_to( lda*sizeof(double), 16 ) )
 	{
 		use_ref = TRUE;
 	}

diff --git a/kernels/x86_64/core2-sse3/1f/bli_dotxf_opt_var1.c b/kernels/x86_64/core2-sse3/1f/bli_dotxf_opt_var1.c
